//! Required Area noHref boolean reflection retains actual attributes.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><map>Fallback map<area id=list type=MiXeD nohref=legacy></map><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://area-no-href.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}

#[test]
fn area_no_href_canonical_boolean_accessor_and_actual_presence(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('list'),P=HTMLAreaElement.prototype,a=Object.getOwnPropertyDescriptor(P,'noHref');if(!a||!a.enumerable||!a.configurable||a.get.length!==0||a.set.length!==1||a.get.name!=='get noHref'||a.set.name!=='set noHref'||Object.hasOwn(x,'noHref')||x.noHref!==true||x.getAttribute('nohref')!=='legacy'||x.type!=='MiXeD'||document.createElement('area').noHref!==false)throw 'canonical noHref boolean';"#);}
#[test]
fn area_no_href_native_boolean_conversion_identity_and_observer_old_values(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('list'),old=x.getAttributeNode('nohref'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.noHref=false;var records=watch.takeRecords();if(x.noHref!==false||old.ownerElement!==null||old.value!=='legacy'||records.length!==1||records[0].oldValue!=='legacy'||records[0].attributeName!=='nohref')throw 'false removes actual attribute';var calls=0;x.noHref={toString:function(){calls++;return '';},valueOf:function(){calls++;return 0;}};var attr=x.getAttributeNode('nohref');records=watch.takeRecords();if(calls||x.noHref!==true||attr===null||attr.value!==''||records.length!==1||records[0].oldValue!==null||x.type!=='MiXeD'||document.getElementById('neighbor').value!=='seed')throw 'boolean conversion keeps actual record';x.noHref='';if(x.noHref!==false||attr.ownerElement!==null)throw 'empty string is false';"#);}
#[test]
fn area_no_href_inert_exact_namespace_and_independent_copies(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','t:area');if(!(x instanceof HTMLAreaElement)||x.noHref!==false)throw 'inert absent noHref';x.setAttributeNS('urn:foreign','nohref','foreign');x.setAttributeNS(null,'NOHREF','upper');if(x.noHref!==false)throw 'exact noHref namespace and case';x.noHref=true;var attr=x.getAttributeNodeNS(null,'nohref');if(x.noHref!==true||attr===null||attr.value!=='')throw 'inert actual boolean';x.removeAttributeNS('urn:foreign','nohref');x.removeAttributeNS(null,'NOHREF');var clone=x.cloneNode(false),copy=doc.importNode(x,false);if(!(clone instanceof HTMLAreaElement)||!(copy instanceof HTMLAreaElement)||clone.noHref!==true||copy.noHref!==true||copy.ownerDocument!==doc||clone.getAttributeNode('nohref')===attr)throw 'independent boolean copies';clone.noHref=false;if(x.noHref!==true||copy.noHref!==true||clone.noHref!==false)throw 'independent noHref removal';"#);}

#[test]
fn area_no_href_truthiness_does_not_invoke_author_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('list'),a=Object.getOwnPropertyDescriptor(HTMLAreaElement.prototype,'noHref'),calls=0,author={toString:function(){calls++;throw 'conversion';},valueOf:function(){calls++;throw 'conversion';}};for(var value of [false,0,-0,NaN,'',null,undefined,BigInt(0)]){a.set.call(x,value);if(x.noHref!==false||x.hasAttribute('nohref'))throw 'false boolean value';}for(var value of [true,1,-1,Infinity,'false',[],{},new Boolean(false),Symbol('boolean'),BigInt(1),author]){a.set.call(x,value);if(x.noHref!==true||x.getAttribute('nohref')!==''||calls)throw 'true boolean value';}a.set.call(x);if(x.noHref!==false||calls||x.type!=='MiXeD')throw 'missing boolean argument';"#);}
#[test]
fn area_no_href_brand_precedes_hooks_and_keeps_author_override(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('list'),C=HTMLAreaElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'noHref'),calls=0;for(var bad of [{},Object.create(P),document.body,document.createElement('p'),document.createElement('ul'),document.createElement('li'),document.createElement('dl'),document.getElementById('neighbor'),document.createElementNS('urn:foreign','area'),new Document().createElementNS('http://www.w3.org/1999/xhtml','OL')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'noHref getter concrete brand';caught=false;try{a.set.call(bad,{toString:function(){calls++;return '';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'noHref setter brand';}Object.defineProperty(x,'noHref',{value:'author',writable:true,configurable:true});a.set.call(x,false);if(x.noHref!=='author'||x.hasAttribute('nohref'))throw 'canonical attribute authority';delete x.noHref;if(x.noHref!==false||Object.hasOwn(x,'noHref'))throw 'restored inherited boolean';delete window.HTMLAreaElement;if(!(x instanceof C)||Object.getPrototypeOf(x)!==P)throw 'saved canonical interface';"#);}
#[test]
fn area_no_href_raw_attribute_aliases_observe_presence_and_preserve_exact_backing(){let(mut d,mut f,mut p)=fixture();for inert in [false,true]{run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','area');x.noHref=true;"}else{"var x=document.getElementById('list');"});run(&mut d,&mut f,&mut p,r#"var a=x.getAttributeNode('nohref'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});for(var key of ['value','nodeValue','textContent']){a[key]='R\ud800'+key;if(x.noHref!==true||a.value!=='R\ud800'+key||x.getAttributeNode('nohref')!==a)throw 'raw boolean backing';}var old=a.value;x.noHref=true;var records=watch.takeRecords();if(x.noHref!==true||a.value!==''||records.length!==4||records[3].oldValue!==old||x.getAttributeNode('nohref')!==a)throw 'boolean normalization uses current Attr';x.removeAttribute('nohref');if(x.noHref!==false||a.ownerElement!==null)throw 'actual boolean removal';x.setAttributeNS('urn:foreign','nohref','foreign');x.setAttributeNS(null,'NOHREF','upper');if(x.noHref!==false)throw 'exact noHref authority';x.setAttributeNS(null,'nohref','A\udfffZ');if(x.ownerDocument!==document){var clone=x.cloneNode(false);if(!x.noHref||!clone.noHref||clone.getAttributeNodeNS(null,'nohref').value!=='A\udfffZ'||clone.getAttributeNodeNS(null,'nohref')===x.getAttributeNodeNS(null,'nohref'))throw 'raw presence copy';}"#);}}
#[test]
fn area_no_href_saved_child_origin_refuses_before_observation_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('list'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLAreaElement.prototype,'noHref');a.set.call(x,false);if(a.get.call(x)!==false)throw 'same origin boolean';");p.set_location(&crate::navigation::address("https://other-noHref.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for source in ["a.get.call(x);","a.set.call(x,true);"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://area-no-href.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(x.noHref!==false)throw 'origin refusal preserves value';a.set.call(x,true);if(!a.get.call(x)||x.getAttribute('nohref')!=='')throw 'saved boolean recovery';");}

#[test]
fn area_no_href_writer_resource_refusal_is_atomic_and_recovers(){for inert in [false,true]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','area');"}else{"var x=document.getElementById('list');x.noHref=false;"});run(&mut d,&mut f,&mut p,"var watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let limit=p.state.retained_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute("x.noHref=true;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);p.state.retained_limit=limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(x.noHref!==false||watch.takeRecords().length)throw 'atomic noHref refusal';x.noHref=true;var records=watch.takeRecords();if(x.noHref!==true||x.getAttribute('nohref')!==''||records.length!==1||records[0].oldValue!==null)throw 'fresh boolean recovery';");}}}
#[test]
fn area_no_href_reads_charge_names_work_and_deadline_without_string_copy_or_retained_growth(){for inert in [false,true]{for mode in 0..3{let(mut d,mut f,mut p)=fixture();let object=if inert{let Value::Host(object)=p.runtime.execute("var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','area');x.noHref=true;x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("inert OL")};object}else{node_handle((0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("list")).unwrap())};let before=format!("{:?}",d.nodes);let retained=p.state.retained;let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.execution_deadline=Some(Instant::now()),_=>{p.state.retained_limit=retained;p.state.copy_work=0;p.state.limits.host.string_bytes=0;}}let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.area_no_href_get(object);if mode==2{assert!(matches!(result,Ok(Value::Bool(true))));}else{assert!(result.is_err());}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.retained,retained);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();assert!(matches!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.area_no_href_get(object),Ok(Value::Bool(true))));}}}